    if ((lib.uniffi_dak_core_checksum_method_dakkern_aufbewahrung() and 0xFFFF) != 30971) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if ((lib.uniffi_dak_core_checksum_method_dakkern_benachrichtigungen() and 0xFFFF) != 57344) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
