sealed class DakFehler: kotlin.Exception() {
    
    class Fehler(
        
        val `code`: kotlin.UInt, 
        
        val `meldung`: kotlin.String
        ) : DakFehler() {
        override val message
            get() = "code=${ `code` }, meldung=${ `meldung` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DakFehler> {
        override fun lift(error_buf: RustBuffer.ByValue): DakFehler = FfiConverterTypeDakFehler.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeDakFehler : FfiConverterRustBuffer<DakFehler> {
    override fun read(buf: ByteBuffer): DakFehler {
        

        return when(buf.getInt()) {
            1 -> DakFehler.Fehler(
                FfiConverterUInt.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DakFehler): ULong {
        return when(value) {
            is DakFehler.Fehler -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`meldung`)
            )
        }
    }

    override fun write(value: DakFehler, buf: ByteBuffer) {
        when(value) {
            is DakFehler.Fehler -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`code`, buf)
                FfiConverterString.write(value.`meldung`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




