sealed class KernLage {
    
    object NichtEingerichtet : KernLage()
    
    
    data class Gesperrt(
        val `generation`: kotlin.ULong, 
        val `generationH`: kotlin.ULong, 
        val `kkUmhuellung`: kotlin.ByteArray?, 
        val `kkHUmhuellung`: kotlin.ByteArray?) : KernLage()
        
    {
        

        companion object
    }
    
    object Entsperrt : KernLage()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeKernLage : FfiConverterRustBuffer<KernLage>{
    override fun read(buf: ByteBuffer): KernLage {
        return when(buf.getInt()) {
            1 -> KernLage.NichtEingerichtet
            2 -> KernLage.Gesperrt(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterOptionalByteArray.read(buf),
                FfiConverterOptionalByteArray.read(buf),
                )
            3 -> KernLage.Entsperrt
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: KernLage): ULong = when(value) {
        is KernLage.NichtEingerichtet -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is KernLage.Gesperrt -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`generation`)
                + FfiConverterULong.allocationSize(value.`generationH`)
                + FfiConverterOptionalByteArray.allocationSize(value.`kkUmhuellung`)
                + FfiConverterOptionalByteArray.allocationSize(value.`kkHUmhuellung`)
            )
        }
        is KernLage.Entsperrt -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: KernLage, buf: ByteBuffer) {
        when(value) {
            is KernLage.NichtEingerichtet -> {
                buf.putInt(1)
                Unit
            }
            is KernLage.Gesperrt -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`generation`, buf)
                FfiConverterULong.write(value.`generationH`, buf)
                FfiConverterOptionalByteArray.write(value.`kkUmhuellung`, buf)
                FfiConverterOptionalByteArray.write(value.`kkHUmhuellung`, buf)
                Unit
            }
            is KernLage.Entsperrt -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






